import assert from 'node:assert/strict';

function readPose({id,selector='.nw-motion-dialog iframe',gid,progress}){
 const f=document.querySelector(selector),d=f.contentDocument,n=d.querySelector('[data-id="'+id+'"]'),clock=f.contentWindow.__NAG_SCROLL_DIRECTOR[gid||d.querySelector('.sc').dataset.id];if(progress!=null)clock.set(progress);
 return {vars:['x','y','z','rx','ry','scale','rot','opacity','blur'].map(k=>n.style.getPropertyValue('--nw-sd-'+k)),base:[n.style.left,n.style.top,n.style.width,n.style.getPropertyValue('--rot')],progress:clock.progress()};
}
export async function runMotionPointsSmoke(page){
 const previous=await page.evaluate(()=>({project:JSON.stringify(project),curPage,curSec,curEl,curPane,selection,secFocus,mode:NAGWEB_STORY_EDITOR.canvasMode(),timeline:NAGWEB_STORY_TIMELINE_UI.state()}));
 try{
  await page.evaluate(()=>{project.pages[0].sections=[mkSection({layout:'free',sdEnabled:false,elements:[]})];curPage=0;curSec=0;curEl=0;selection=[];secFocus=false;saveProject();renderPane();renderPreview();history=[];future=[];});
  const before=await page.evaluate(()=>({project:JSON.stringify(project),stored:localStorage.getItem(STORE_KEY),factory:NAGWEB_MOTION_LAB.create().scene.elements}));
  async function frame(){await page.waitForFunction(()=>document.querySelector('.nw-motion-dialog iframe')?.contentDocument?.querySelector('.im-hov[data-motion-canvas]'));return (await page.$('.nw-motion-dialog iframe')).contentFrame();}
  async function select(id){const f=await frame(),n=await f.$(id?'[data-id="'+id+'"]':'.im-hov');await n.focus();await page.keyboard.press('Space');return n.evaluate(n=>n.dataset.id);}
  async function points(){const list=await page.$$eval('[data-motion-key] option',ns=>ns.map(n=>({id:n.value,at:parseFloat(n.textContent)})));assert.deepEqual(await page.$$eval('[data-motion-key-jump]',ns=>ns.map(n=>({id:n.dataset.motionKeyJump,at:parseFloat(n.textContent)}))),list);return list;}
  async function moment(at){const list=await points();await page.click('[data-motion-key-jump="'+list.find(k=>k.at===at).id+'"]');}
  async function scrub(at){await page.$eval('[data-motion-progress]',(n,at)=>{n.value=String(at);n.dispatchEvent(new Event('input',{bubbles:true}));},at);}
  async function pose(id,progress){return page.evaluate(readPose,{id,progress});}
  await page.click('.tb-left [data-motion-open]');const id=await select(),originalPoints=await points();await scrub(10.5);const initial=await pose(id);assert.equal(initial.vars[2],'-285.44px');
  const iframe=await page.$('.nw-motion-dialog iframe');await iframe.evaluate(f=>f.dataset.pointsProbe='unchanged');
  await page.click('[data-motion-key-add]');const addedPoints=await points(),newKey=addedPoints.find(k=>k.at===10.5);assert.deepEqual(addedPoints.map(k=>k.at),[0,10.5,35,65,100]);assert.ok(newKey?.id&&!originalPoints.some(k=>k.id===newKey.id));assert.equal(await page.$eval('[data-motion-key]',n=>n.value),newKey.id);assert.deepEqual(await pose(id),initial,'Adding captures the evaluated pose without a visible jump');assert.equal(await iframe.evaluate(f=>f.dataset.pointsProbe),'unchanged','Point edits use the current iframe/runtime');
  await page.click('[data-motion-key-add]');assert.deepEqual(await points(),addedPoints,'Adding at an existing moment never duplicates or replaces it');
  await page.$eval('[data-motion-key-property="z"]',n=>{n.value='-200';n.dispatchEvent(new Event('change',{bubbles:true}));});assert.equal((await pose(id)).vars[2],'-200.00px');
  await moment(35);const deleted=originalPoints.find(k=>k.at===35);await page.click('[data-motion-key-remove]');const preparedPoints=await points();assert.deepEqual(preparedPoints.map(k=>k.at),[0,10.5,65,100]);assert.ok(!preparedPoints.some(k=>k.id===deleted.id));assert.equal(await page.$eval('[data-motion-key]',n=>n.value),newKey.id,'Removing selects the nearest surviving moment');const prepared=await pose(id,.5);
  await page.click('[data-motion-template="soft-orbit"]');await page.waitForFunction(()=>document.querySelector('.nw-motion-dialog iframe')?.contentDocument?.querySelector('.hd')?.textContent==='Diseño en movimiento.');await page.click('[data-motion-template="iso-focus"]');await page.waitForFunction(id=>document.querySelector('.nw-motion-dialog iframe')?.contentDocument?.querySelector('[data-id="'+id+'"].nw-motion-selected'),{},id);assert.deepEqual(await points(),preparedPoints);
  assert.equal(await page.evaluate(()=>JSON.stringify(project)),before.project);assert.equal(await page.evaluate(()=>localStorage.getItem(STORE_KEY)),before.stored);assert.equal(await page.evaluate(()=>history.length),0);
  await page.click('[data-motion-insert-group]');const inserted=await page.evaluate(id=>({project:JSON.stringify(project),group:sec().elements.find(e=>e.nwMotionInstance),element:sec().elements.find(e=>e.id===id),images:sec().elements.filter(e=>e.type==='image')}),id);
  const strip=ks=>ks.map(({id,...k})=>k);assert.deepEqual(inserted.element.sdKeyframes.map(k=>({id:k.id,at:k.at})),preparedPoints);assert.deepEqual(inserted.element.sdKeyframes.filter(k=>k.id!==newKey.id),originalPoints.filter(k=>k.id!==deleted.id).map(k=>({...before.factory[0].sdKeyframes.find(f=>f.at===k.at),id:k.id})));const newFrame=inserted.element.sdKeyframes.find(k=>k.id===newKey.id);assert.equal(newFrame.z,-200);assert.ok(Math.abs(newFrame.rotateX-28.544)<1e-8);assert.ok(Math.abs(newFrame.rotateY+35.68)<1e-8);assert.equal(newFrame.ease,'cinematic');for(let i=1;i<3;i++)assert.deepEqual(strip(inserted.images[i].sdKeyframes),strip(before.factory[i].sdKeyframes));
  await page.evaluate(()=>undo());assert.equal(await page.evaluate(()=>JSON.stringify(project)),before.project);await page.evaluate(()=>redo());assert.equal(await page.evaluate(()=>JSON.stringify(project)),inserted.project);
  await page.evaluate(gid=>NAGWEB_MOTION_LAB.edit(gid),inserted.group.id);await select(id);assert.deepEqual(await points(),preparedPoints);await moment(65);await page.click('[data-motion-key-remove]');await scrub(50);await page.click('[data-motion-key-add]');const savedPoints=await points();assert.deepEqual(savedPoints.map(k=>k.at),[0,10.5,50,100]);const savedPreview=await pose(id,.7);await page.click('[data-motion-save]');const saved=await page.evaluate(id=>({project:JSON.stringify(project),element:sec().elements.find(e=>e.id===id),groups:sec().elements.filter(e=>e.nwMotionInstance).length}),id);assert.equal(saved.groups,1);assert.deepEqual(saved.element.sdKeyframes.map(k=>({id:k.id,at:k.at})),savedPoints);
  await page.evaluate(gid=>NAGWEB_MOTION_LAB.edit(gid),inserted.group.id);await select(id);await moment(50);await page.click('[data-motion-key-remove]');await moment(10.5);await page.click('[data-motion-key-remove]');assert.deepEqual((await points()).map(k=>k.at),[0,100]);assert.equal(await page.$eval('[data-motion-key-remove]',n=>n.disabled),true);await page.click('[data-motion-key-remove]');assert.equal((await points()).length,2,'Two moments remain');await scrub(12.3);await page.click('[data-motion-key-add]');assert.deepEqual((await points()).map(k=>k.at),[0,12.3,100]);await page.click('[data-motion-close]');assert.equal(await page.evaluate(()=>JSON.stringify(project)),saved.project,'Closing discards point changes');
  await page.evaluate(()=>undo());assert.equal(await page.evaluate(()=>JSON.stringify(project)),inserted.project);await page.evaluate(()=>redo());assert.equal(await page.evaluate(()=>JSON.stringify(project)),saved.project);
  await page.evaluate(()=>{const f=document.createElement('iframe');f.id='points-export';f.srcdoc=generateSite(flattenPage(page()),false,false,false);document.body.append(f);});await page.waitForFunction(gid=>document.querySelector('#points-export')?.contentWindow?.__NAG_SCROLL_DIRECTOR?.[gid],{},inserted.group.id);const exported=await page.evaluate(readPose,{id,selector:'#points-export',gid:inserted.group.id,progress:.7});assert.deepEqual(exported.vars,savedPreview.vars,'Saved/exported moments reproduce the Lab pose');assert.deepEqual(prepared.base,initial.base,'Point edits preserve base geometry');
  console.log('Momentos nuevos Motion Lab: pose interpolada sin salto, decimales, sin duplicados, quitar/seleccionar, mínimo dos, IDs/otros elementos, borradores, insertar/guardar/cancelar, historial y exportación OK');
 }finally{
  await page.evaluate(p=>{document.querySelector('.nw-motion-dialog').close();document.querySelector('#points-export')?.remove();clearTimeout(previewTimer);project=JSON.parse(p.project);curPage=p.curPage;curSec=p.curSec;curEl=p.curEl;curPane=p.curPane;selection=p.selection;secFocus=p.secFocus;history=[];future=[];NAGWEB_STORY_EDITOR.setCanvasMode(p.mode);NAGWEB_STORY_TIMELINE_UI.setState(p.timeline);saveProject();renderScenes();renderPane();renderPreview();},previous);
 }
}
